head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > executeParallel]<br/>여러 submission 을 병렬(Parallel)로 동시 호출하고, 모든 응답이 완료되면 콜백을 실행합니다.",
    "validation" : [
        "Workflow 를 별도로 생성하지 않고 submission ID 배열만으로 병렬 실행을 수행합니다.",
        "submissionId(필수) 파라미터로 실행할 submission ID 문자열 배열을 설정할 수 있어야 합니다.",
        "processMsg(선택) 파라미터로 실행 중 표시할 프로세스 메시지를 설정할 수 있어야 합니다.",
        "resolveCallback(선택) 파라미터로 모든 submission 이 성공적으로 완료된 후 호출되는 콜백 함수를 설정할 수 있어야 합니다.",
        "rejectCallback(선택) 파라미터로 오류 발생 시 호출되는 콜백 함수를 설정할 수 있어야 합니다.",
        "id(선택) 파라미터로 Workflow ID 를 설정할 수 있어야 합니다. (기본값 : 'parallelTemp')"
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 요청 body 캡처용 (각 submission 별 requestData 검증)
scwin.capturedBodies = [];

// XHR.send 후킹 - 실제 전송 body 가로채기
(function () {
    var originalSend = XMLHttpRequest.prototype.send;
    XMLHttpRequest.prototype.send = function (body) {
        try {
            if (scwin.captureEnabled) {
                scwin.capturedBodies.push(typeof body === "string" ? body : String(body));
            }
        } catch (e) {}
        return originalSend.apply(this, arguments);
    };
})();



scwin.btn_executeParallel_onclick = function () {
    var scenario = par_scenario.getValue();

    // 매 시나리오 실행 전 캡처 초기화
    scwin.capturedBodies = [];
    scwin.captureEnabled = false;

    if (scenario === "1") {
        // 시나리오 1 : 기본 병렬 실행 - submissionId 배열 3개 모두 성공 (id 생략 → 기본값 'parallelTemp' 확인)
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 1 : 기본 병렬 실행 (id 생략 시 기본값 'parallelTemp') ──");
        $p.executeParallel(
            ["sbm_p1", "sbm_p2", "sbm_p3"],
            "$blank",
            function (workflowObj) {
                var resultObj = (workflowObj && workflowObj.result) ? workflowObj.result : {};
                var keys = (typeof resultObj === "object" && resultObj !== null) ? Object.keys(resultObj) : [];
                var len = Array.isArray(resultObj) ? resultObj.length : keys.length;
                var wfId = (workflowObj && workflowObj.id) ? workflowObj.id : "-";
                wf_body_bottom.getObj("scwin").setReturnValue(
                    "resolveCallback 호출됨 / 완료된 submission 수 = " + len + " / workflowObj.id = '" + wfId + "'"
                );
                wf_body_bottom.getObj("scwin").setReturnValue("result 키 : [" + keys.join(", ") + "]");
                wf_body_bottom.getObj("scwin").setReturnValue(
                    "[검증] id 생략 시 기본값 'parallelTemp' 포함 여부 : " + (typeof wfId === "string" && wfId.indexOf("parallelTemp") > -1)
                );
                $p.hideProcessMessage();
            },
            function (workflowObj) {
                wf_body_bottom.getObj("scwin").setReturnValue("rejectCallback 호출됨 (예상 : resolveCallback)");
                $p.hideProcessMessage();
            }
        );
    } else if (scenario === "2") {
        // 시나리오 2 : 선택 파라미터(processMsg / id / rejectCallback) 설정
        // - 오류 유발용 동적 submission 을 포함시켜 rejectCallback 호출 유도
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 2 : 선택 파라미터(processMsg / id / rejectCallback) 설정 ──");

        var customId = "parallel_customId";

        // 오류 유발용 동적 submission 생성 (존재하지 않는 URL)
        $p.createSubmission({
            id : "sbm_fail",
            action : "/data/p_parallel_not_exist.json",
            method : "post",
            mediatype : "application/json"
        });

        $p.executeParallel(
            ["sbm_p1", "sbm_fail", "sbm_p3"],
            "Parallel Processing...",
            function (workflowObj) {
                wf_body_bottom.getObj("scwin").setReturnValue("resolveCallback 호출됨 (예상 : rejectCallback)");
                $p.hideProcessMessage();
            },
            function (workflowObj) {
                var wfId = (workflowObj && workflowObj.id) ? workflowObj.id : "-";
                wf_body_bottom.getObj("scwin").setReturnValue("rejectCallback 호출됨 (submit 오류 발생)");
                wf_body_bottom.getObj("scwin").setReturnValue("workflowObj.id : '" + wfId + "' / customId 포함 여부 : " + (typeof wfId === "string" && wfId.indexOf(customId) > -1));
                $p.hideProcessMessage();
            },
            customId
        );
    }
};
